  align-items: center;
  gap: 0.5rem;
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-primary:active { transform: scale(0.97); }

/* ─── Divider ─── */
.divider {
  width: 100%;
  height: 5px;
  background: linear-gradient(to right, var(--accent), rgba(229,9,20,0.3), transparent);
  border: none;
}

/* ─── Sections ─── */
.section {
  padding: 4.5rem 0;
}
.section-heading {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  margin-bottom: 2rem;
  letter-spacing: -0.01em;
}

/* ─── Trending Carousel ─── */
.trending { padding: 4.5rem 0 6rem; }
.carousel-wrapper { position: relative; }
.carousel {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0.5rem 0;
}
.carousel::-webkit-scrollbar { display: none; }
.carousel-card {
  flex: 0 0 auto;
  width: clamp(180px, 18vw, 220px);
  position: relative;
  scroll-snap-align: start;
  cursor: pointer;
  transition: transform 0.2s ease;
}
.carousel-card:hover { transform: scale(1.03); }
.carousel-card-poster {
  width: 100%;
  aspect-ratio: 2/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  background: var(--bg-card);
}
.carousel-card-poster img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.carousel-rank {
  position: absolute;
  left: -0.5rem;
  bottom: -0.25rem;
  font-size: clamp(4rem, 6vw, 7rem);
  font-weight: 900;
  line-height: 0.75;
  color: #000;
  -webkit-text-stroke: 2px rgba(255,255,255,0.5);
  text-stroke: 2px rgba(255,255,255,0.5);
  letter-spacing: -0.04em;
  z-index: 2;
  pointer-events: none;
  font-family: var(--font-display);
}
.carousel-card-title {
  margin-top: 0.75rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
}
.carousel-arrow {
  position: absolute;
  top: 40%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(0,0,0,0.7);
  border: 1px solid var(--border);
  color: var(--text-primary);
  font-size: 1.25rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}
.carousel-arrow:hover { background: rgba(50,50,50,0.8); }
.carousel-arrow-left { left: -1rem; }
.carousel-arrow-right { right: -1rem; }

