  font-size: 0.9375rem;
  line-height: 1.5;
}
.feature-icon {
  position: absolute;
  bottom: 1rem;
  right: 1rem;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.5;
}
.feature-icon svg { width: 28px; height: 28px; }

/* ─── FAQ ─── */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-width: 900px;
}
.faq-item {
  background: var(--bg-card);
  border-radius: var(--radius);
  overflow: hidden;
  transition: background 0.15s ease;
}
.faq-item:hover { background: #222; }
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.125rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-sans);
  transition: background 0.15s ease, color 0.15s ease;
}
.faq-question:hover { color: var(--accent); }
.faq-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  font-size: 1.5rem;
  font-weight: 300;
  color: var(--text-secondary);
}
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer-wrapper {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.faq-item.open .faq-answer-wrapper { grid-template-rows: 1fr; }
.faq-answer-inner { overflow: hidden; }
.faq-answer {
  padding: 0 1.5rem 1.5rem;
  color: var(--text-secondary);
  font-size: 1rem;
  line-height: 1.6;
}

/* ─── Bottom CTA ─── */
.cta-section { padding: 4.5rem 0 6rem; }
.cta-content {
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.cta-content .hero-prompt { margin-bottom: 1.25rem; }

/* ─── Footer ─── */
.footer {
  padding: 4rem 0 3rem;
  border-top: 1px solid var(--border);
}
.footer-contact {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 0.9375rem;
}
.footer-contact a {
  color: var(--text-secondary);
  text-decoration: underline;
  text-underline-offset: 3px;
}
.footer-contact a:hover { color: var(--text-primary); }
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem 2rem;
}
.footer-col {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.footer-col a {
  color: var(--text-secondary);
  text-decoration: underline;
  text-underline-offset: 3px;
  font-size: 0.8125rem;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  margin-top: 2.5rem;
}
.footer-bottom .lang-select { margin-bottom: 1.5rem; }
.footer-legal {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* ─── Responsive ─── */
@media (max-width: 768px) {
  .section { padding: 3rem 0; }
  .trending { padding: 3rem 0 4.5rem; }
  .hero-form { flex-direction: column; }
  .btn-primary { justify-content: center; }
  .carousel-card { width: 150px; }
  .carousel-arrow { display: none; }
  .features-grid { grid-template-columns: 1fr; }
  .header-right { gap: 0.5rem; }
  .lang-select { font-size: 0.75rem; padding: 0.35rem 1.75rem 0.35rem 0.5rem; }
  .btn-signin { font-size: 0.75rem; padding: 0.35rem 0.875rem; }
  .logo { font-size: 1.5rem; }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .header-inner { padding: 0 1rem; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
</style>
